/**
 * Tests for
 * {@link SpringMVCWebProcessingContextBuilder#createApplicationContext(org.thymeleaf.testing.templateengine.testable.ITest,
 * javax.servlet.ServletContext, java.util.Locale, java.util.Map)}.
 */
public class SpringMVCWebProcessingContextBuilderCreateApplicationContextTests {


    private static final String INVALID_SHARED_CONFIG_MESSAGE =
            "Invalid configuration for context builder. Builder is configured to share Spring " +
            "application context across executions, but more than one different context config " +
            "locations are being used, so this option cannot be used.";


    private SpringMVCWebProcessingContextBuilder builder;
    private ServletContext servletContext;
    private Locale locale;
    private Map<String, Object> variables;


    @BeforeEach
    public void setUp() {
        this.builder = new SpringMVCWebProcessingContextBuilder();
        this.servletContext = Mockito.mock(ServletContext.class);
        // Spring's web environments iterate over the servlet context init parameters during refresh
        Mockito.when(this.servletContext.getInitParameterNames())
                .thenReturn(Collections.emptyEnumeration());
        // Spring registers servlet context attributes as beans while refreshing web contexts
        Mockito.when(this.servletContext.getAttributeNames())
                .thenReturn(Collections.emptyEnumeration());
        this.locale = Locale.ENGLISH;
        this.variables = new HashMap<String, Object>();
    }


    private WebApplicationContext createApplicationContext() {
        return this.builder.createApplicationContext(null, this.servletContext, this.locale, this.variables);
    }


    private static String writeApplicationContextXml(final Path directory, final String fileName)
            throws Exception {
        final Path xmlFile = directory.resolve(fileName);
        Files.write(xmlFile, Arrays.asList(
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>",
                "<beans xmlns=\"http://www.springframework.org/schema/beans\"",
                "       xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"",
                "       xsi:schemaLocation=\"http://www.springframework.org/schema/beans" +
                        " https://www.springframework.org/schema/beans/spring-beans.xsd\">",
                "  <bean id=\"xmlBean\" class=\"java.lang.String\">",
                "    <constructor-arg value=\"xmlBeanValue\"/>",
                "  </bean>",
                "</beans>"), StandardCharsets.UTF_8);
        return xmlFile.toUri().toString();
    }


    /*
     * Already existing application context (externally configured): it must be returned as-is.
     */

    @Test
    public void testExternallyConfiguredApplicationContextIsReturnedAsIs() {
        final StaticWebApplicationContext preConfigured = new StaticWebApplicationContext();
        preConfigured.setServletContext(this.servletContext);
        this.builder.setApplicationContext(preConfigured);
        // Even with a (conflicting) sharing configuration, the fixed application context wins
        this.builder.setShareAppContextForAllTests(true);
        this.builder.setConfigurationClasses(TestConfiguration.class);
        this.builder.setApplicationContextConfigLocation("classpath:does-not-matter.xml");

        final WebApplicationContext result = createApplicationContext();

        assertSame(preConfigured, result);
        assertSame(preConfigured, createApplicationContext());
    }


    /*
     * Configuration classes present: an AnnotationConfigWebApplicationContext is created.
     */

    @Test
    public void testConfigurationClassesProduceAnnotationConfigWebApplicationContext() {
        this.builder.setConfigurationClasses(TestConfiguration.class);

        final WebApplicationContext result = createApplicationContext();

        assertNotNull(result);
        assertTrue(result instanceof AnnotationConfigWebApplicationContext);
        assertSame(this.servletContext, result.getServletContext());
        assertTrue(result.containsBean("testBean"));
        assertEquals("testBeanValue", result.getBean("testBean"));
    }

    @Test
    public void testConfigurationClassesAreNotSharedByDefault() {
        this.builder.setConfigurationClasses(TestConfiguration.class);

        final WebApplicationContext first = createApplicationContext();
        final WebApplicationContext second = createApplicationContext();

        assertNotSame(first, second);
        assertTrue(first instanceof AnnotationConfigWebApplicationContext);
        assertTrue(second instanceof AnnotationConfigWebApplicationContext);
        assertEquals("testBeanValue", second.getBean("testBean"));
    }

    @Test
    public void testConfigurationClassesAreSharedWhenSharingIsEnabled() {
        this.builder.setConfigurationClasses(TestConfiguration.class);
        this.builder.setShareAppContextForAllTests(true);

        final WebApplicationContext first = createApplicationContext();
        final WebApplicationContext second = createApplicationContext();
        final WebApplicationContext third = createApplicationContext();

        assertTrue(first instanceof AnnotationConfigWebApplicationContext);
        assertSame(first, second);
        assertSame(first, third);
        assertEquals("testBeanValue", third.getBean("testBean"));
    }


    /*
     * No configuration classes and no config location: empty static context.
     */

    @Test
    public void testNoConfigurationProducesEmptyStaticWebApplicationContext() {
        this.builder.setApplicationContextConfigLocation(null);

        final WebApplicationContext result = createApplicationContext();

        assertNotNull(result);
        assertTrue(result instanceof StaticWebApplicationContext);
        assertSame(this.servletContext, result.getServletContext());
        assertEquals(0, ((StaticWebApplicationContext) result).getBeanDefinitionCount());
    }

    @Test
    public void testNoConfigurationContextIsNotSharedByDefault() {
        this.builder.setApplicationContextConfigLocation(null);

        final WebApplicationContext first = createApplicationContext();
        final WebApplicationContext second = createApplicationContext();

        assertTrue(first instanceof StaticWebApplicationContext);
        assertTrue(second instanceof StaticWebApplicationContext);
        assertNotSame(first, second);
    }

    @Test
    public void testNoConfigurationContextIsSharedWhenSharingIsEnabled() {
        this.builder.setApplicationContextConfigLocation(null);
        this.builder.setShareAppContextForAllTests(true);

        final WebApplicationContext first = createApplicationContext();

        assertTrue(first instanceof StaticWebApplicationContext);
        assertSame(first, createApplicationContext());
        assertSame(first, createApplicationContext());
    }

    @Test
    public void testEmptyConfigurationClassesArrayIsTreatedAsNoConfigurationClasses() {
        this.builder.setConfigurationClasses(new Class<?>[0]);
        this.builder.setApplicationContextConfigLocation(null);

        final WebApplicationContext result = createApplicationContext();

        assertTrue(result instanceof StaticWebApplicationContext);
        assertSame(this.servletContext, result.getServletContext());
    }


    /*
     * XML config location: context is created from the given location.
     */

    @Test
    public void testXmlApplicationContextIsCreatedFromConfigLocation(@TempDir final Path tempDir) throws Exception {
        final String configLocation = writeApplicationContextXml(tempDir, "applicationContext.xml");
        this.builder.setApplicationContextConfigLocation(configLocation);

        final WebApplicationContext result = createApplicationContext();

        assertNotNull(result);
        assertTrue(result instanceof XmlWebApplicationContext);
        assertSame(this.servletContext, result.getServletContext());
        assertTrue(result.containsBean("xmlBean"));
        assertEquals("xmlBeanValue", result.getBean("xmlBean"));
    }

    @Test
    public void testXmlApplicationContextIsNotSharedByDefault(@TempDir final Path tempDir) throws Exception {
        this.builder.setApplicationContextConfigLocation(
                writeApplicationContextXml(tempDir, "applicationContext.xml"));

        final WebApplicationContext first = createApplicationContext();
        final WebApplicationContext second = createApplicationContext();

        assertTrue(first instanceof XmlWebApplicationContext);
        assertTrue(second instanceof XmlWebApplicationContext);
        assertNotSame(first, second);
        assertEquals("xmlBeanValue", second.getBean("xmlBean"));
    }

    @Test
    public void testXmlApplicationContextIsSharedWhenSharingIsEnabled(@TempDir final Path tempDir) throws Exception {
        this.builder.setApplicationContextConfigLocation(
                writeApplicationContextXml(tempDir, "applicationContext.xml"));
        this.builder.setShareAppContextForAllTests(true);

        final WebApplicationContext first = createApplicationContext();
        final WebApplicationContext second = createApplicationContext();

        assertTrue(first instanceof XmlWebApplicationContext);
        assertSame(first, second);
    }

    @Test
    public void testConfigurationClassesTakePrecedenceOverConfigLocation(@TempDir final Path tempDir) throws Exception {
        this.builder.setConfigurationClasses(TestConfiguration.class);
        this.builder.setApplicationContextConfigLocation(
                writeApplicationContextXml(tempDir, "applicationContext.xml"));

        final WebApplicationContext result = createApplicationContext();

        assertTrue(result instanceof AnnotationConfigWebApplicationContext);
        assertFalse(result.containsBean("xmlBean"));
        assertTrue(result.containsBean("testBean"));
    }


    /*
     * Missing / broken XML config locations.
     */

    @Test
    public void testMissingXmlConfigLocationRaisesTestEngineExecutionException() {
        final String configLocation =
                "classpath:org/thymeleaf/testing/templateengine/spring5/context/web/no-such-applicationContext.xml";
        this.builder.setApplicationContextConfigLocation(configLocation);

        final TestEngineExecutionException exception =
                assertThrows(TestEngineExecutionException.class, () -> createApplicationContext());

        assertTrue(exception.getMessage().contains(configLocation));
        assertTrue(exception.getCause() instanceof BeanDefinitionStoreException);
        assertTrue(exception.getCause().getCause() instanceof FileNotFoundException);
    }

    @Test
    public void testMissingXmlConfigLocationDoesNotCorruptSharedState(@TempDir final Path tempDir) throws Exception {
        this.builder.setShareAppContextForAllTests(true);
        this.builder.setApplicationContextConfigLocation(
                "classpath:org/thymeleaf/testing/templateengine/spring5/context/web/no-such-applicationContext.xml");
        assertThrows(TestEngineExecutionException.class, () -> createApplicationContext());

        // Nothing was cached for the failed location, so a different (valid) location can be used
        this.builder.setApplicationContextConfigLocation(
                writeApplicationContextXml(tempDir, "applicationContext.xml"));
        final WebApplicationContext result = createApplicationContext();

        assertTrue(result instanceof XmlWebApplicationContext);
        assertEquals("xmlBeanValue", result.getBean("xmlBean"));
        assertSame(result, createApplicationContext());
    }

    @Test
    public void testBrokenXmlConfigLocationRethrowsBeanDefinitionStoreException(@TempDir final Path tempDir)
            throws Exception {
        final Path brokenXml = tempDir.resolve("broken-applicationContext.xml");
        Files.write(brokenXml, Arrays.asList(
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>",
                "<beans><bean id=\"unclosed\"></beans>"), StandardCharsets.UTF_8);
        this.builder.setApplicationContextConfigLocation(brokenXml.toUri().toString());

        final BeanDefinitionStoreException exception =
                assertThrows(BeanDefinitionStoreException.class, () -> createApplicationContext());

        assertTrue(exception.getCause() instanceof SAXException);
        assertFalse(exception.getCause() instanceof FileNotFoundException);
    }


    /*
     * Sharing across tests: the cache key must be consistent.
     */

    @Test
    public void testSharingWithDifferentConfigurationClassesRaisesRuntimeException() {
        this.builder.setShareAppContextForAllTests(true);
        this.builder.setConfigurationClasses(TestConfiguration.class);
        final WebApplicationContext first = createApplicationContext();
        assertTrue(first instanceof AnnotationConfigWebApplicationContext);

        this.builder.setConfigurationClasses(OtherTestConfiguration.class);

        final RuntimeException exception = assertThrows(RuntimeException.class, () -> createApplicationContext());

        assertEquals(RuntimeException.class, exception.getClass());
        assertEquals(INVALID_SHARED_CONFIG_MESSAGE, exception.getMessage());
    }

    @Test
    public void testSharingWithDifferentConfigLocationsRaisesRuntimeException(@TempDir final Path tempDir)
            throws Exception {
        this.builder.setShareAppContextForAllTests(true);
        this.builder.setApplicationContextConfigLocation(
                writeApplicationContextXml(tempDir, "applicationContext.xml"));
        final WebApplicationContext first = createApplicationContext();
        assertTrue(first instanceof XmlWebApplicationContext);

        this.builder.setApplicationContextConfigLocation(
                writeApplicationContextXml(tempDir, "other-applicationContext.xml"));

        final RuntimeException exception = assertThrows(RuntimeException.class, () -> createApplicationContext());

        assertEquals(RuntimeException.class, exception.getClass());
        assertEquals(INVALID_SHARED_CONFIG_MESSAGE, exception.getMessage());
    }

    @Test
    public void testSharingEmptyContextThenConfigLocationRaisesRuntimeException(@TempDir final Path tempDir)
            throws Exception {
        this.builder.setShareAppContextForAllTests(true);
        this.builder.setApplicationContextConfigLocation(null);
        final WebApplicationContext first = createApplicationContext();
        assertTrue(first instanceof StaticWebApplicationContext);
        assertSame(first, createApplicationContext());

        this.builder.setApplicationContextConfigLocation(
                writeApplicationContextXml(tempDir, "applicationContext.xml"));

        final RuntimeException exception = assertThrows(RuntimeException.class, () -> createApplicationContext());

        assertEquals(RuntimeException.class, exception.getClass());
        assertEquals(INVALID_SHARED_CONFIG_MESSAGE, exception.getMessage());
    }

    @Test
    public void testSharingConfigurationClassesThenNoConfigurationRaisesRuntimeException() {
        this.builder.setShareAppContextForAllTests(true);
        this.builder.setConfigurationClasses(TestConfiguration.class);
        assertTrue(createApplicationContext() instanceof AnnotationConfigWebApplicationContext);

        this.builder.setConfigurationClasses((Class<?>[]) null);
        this.builder.setApplicationContextConfigLocation(null);

        final RuntimeException exception = assertThrows(RuntimeException.class, () -> createApplicationContext());

        assertEquals(RuntimeException.class, exception.getClass());
        assertEquals(INVALID_SHARED_CONFIG_MESSAGE, exception.getMessage());
    }

    @Test
    public void testSharedContextIsNotRecreatedWhenConfigurationIsUnchanged() {
        // Two different configurations that produce the same cache key are impossible, but the
        // same configuration expressed twice must reuse the same shared context instance.
        this.builder.setShareAppContextForAllTests(true);
        this.builder.setConfigurationClasses(TestConfiguration.class);
        final WebApplicationContext first = createApplicationContext();

        this.builder.setConfigurationClasses(TestConfiguration.class);
        final WebApplicationContext second = createApplicationContext();

        assertSame(first, second);
    }


    @Configuration
    public static class TestConfiguration {

        @Bean(name = "testBean")
        public String testBean() {
            return "testBeanValue";
        }

    }


    @Configuration
    public static class OtherTestConfiguration {

        @Bean(name = "otherTestBean")
        public String otherTestBean() {
            return "otherTestBeanValue";
        }

    }

}

