class SpringMVCWebProcessingContextBuilderCreateApplicationContextTests {

    private static final Locale LOCALE = Locale.ENGLISH;
    private static final Map<String,Object> VARIABLES = Collections.emptyMap();

    private SpringMVCWebProcessingContextBuilder builder;
    private ServletContext servletContext;
    private ITest test;


    @BeforeEach
    void setUp() {
        this.builder = new SpringMVCWebProcessingContextBuilder();
        this.servletContext = mock(ServletContext.class);
        when(this.servletContext.getInitParameterNames()).thenReturn(Collections.emptyEnumeration());
        when(this.servletContext.getAttributeNames()).thenReturn(Collections.emptyEnumeration());
        this.test = mock(ITest.class);
    }


    private WebApplicationContext createApplicationContext() {
        return this.builder.createApplicationContext(this.test, this.servletContext, LOCALE, VARIABLES);
    }


    @Test
    void returnsExplicitlyConfiguredApplicationContextWithoutApplyingOtherConfiguration() {
        final WebApplicationContext configuredContext = mock(WebApplicationContext.class);
        this.builder.setApplicationContext(configuredContext);
        this.builder.setShareAppContextForAllTests(true);
        this.builder.setApplicationContextConfigLocation("classpath:this/file/does/not/exist.xml");

        final WebApplicationContext result = createApplicationContext();

        assertSame(configuredContext, result);
    }


    @Test
    void createsAndRefreshesAnnotationConfigContextWhenConfigurationClassesAreSet() {
        this.builder.setConfigurationClasses(FirstConfiguration.class);
        // This intentionally points to a missing XML file: configuration classes must take precedence.
        this.builder.setApplicationContextConfigLocation("classpath:this/file/does/not/exist.xml");

        final WebApplicationContext first = createApplicationContext();
        final WebApplicationContext second = createApplicationContext();

        final AnnotationConfigWebApplicationContext annotationContext =
                assertInstanceOf(AnnotationConfigWebApplicationContext.class, first);
        assertTrue(annotationContext.isActive());
        assertSame(this.servletContext, annotationContext.getServletContext());
        assertEquals("from-first-configuration", annotationContext.getBean("firstBean"));
        assertNotSame(first, second);
        assertInstanceOf(AnnotationConfigWebApplicationContext.class, second);
    }


    @Test
    void treatsEmptyConfigurationClassArrayAsNoConfiguration() {
        this.builder.setConfigurationClasses();
        this.builder.setApplicationContextConfigLocation(null);

        final WebApplicationContext context = createApplicationContext();

        assertInstanceOf(StaticWebApplicationContext.class, context);
        assertSame(this.servletContext, context.getServletContext());
    }


    @Test
    void createsEmptyStaticContextWhenConfigLocationIsNull() {
        this.builder.setApplicationContextConfigLocation(null);

        final WebApplicationContext context = createApplicationContext();

        final StaticWebApplicationContext staticContext =
                assertInstanceOf(StaticWebApplicationContext.class, context);
        assertSame(this.servletContext, staticContext.getServletContext());
        assertEquals(0, staticContext.getBeanDefinitionCount());
        assertFalse(staticContext.isActive());
        assertNotSame(context, createApplicationContext());
    }


    @Test
    void createsRefreshedXmlContextAndLoadsConfiguredBeans(@TempDir final Path tempDir) throws Exception {
        final Path contextFile = tempDir.resolve("applicationContext.xml");
        Files.writeString(contextFile, """
                <?xml version="1.0" encoding="UTF-8"?>
                <beans xmlns="http://www.springframework.org/schema/beans"
                       xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
                       xsi:schemaLocation="http://www.springframework.org/schema/beans https://www.springframework.org/schema/beans/spring-beans.xsd">
                    <bean id="xmlBean" class="java.lang.String">
                        <constructor-arg value="from-xml"/>
                    </bean>
                </beans>
                """);
        this.builder.setApplicationContextConfigLocation(contextFile.toUri().toString());

        final WebApplicationContext context = createApplicationContext();

        final XmlWebApplicationContext xmlContext =
                assertInstanceOf(XmlWebApplicationContext.class, context);
        assertTrue(xmlContext.isActive());
        assertSame(this.servletContext, xmlContext.getServletContext());
        assertEquals("from-xml", xmlContext.getBean("xmlBean"));
    }


    @Test
    void rethrowsBeanDefinitionStoreExceptionWhenXmlIsMalformed(@TempDir final Path tempDir) throws Exception {
        final Path contextFile = tempDir.resolve("malformed.xml");
        Files.writeString(contextFile, "<beans><bean></beans>");
        this.builder.setApplicationContextConfigLocation(contextFile.toUri().toString());

        final BeanDefinitionStoreException exception =
                assertThrows(BeanDefinitionStoreException.class, this::createApplicationContext);

        assertNotNull(exception.getCause());
        assertFalse(exception.getCause() instanceof FileNotFoundException);
    }


    @Test
