    private static String readBuffers(final Publisher<? extends DataBuffer> publisher) {
        final List<? extends DataBuffer> buffers = Flux.from(publisher).collectList().block();
        if (buffers == null) {
            return null;
        }
        final StringBuilder result = new StringBuilder();
        for (final DataBuffer buffer : buffers) {
            final byte[] bytes = new byte[buffer.readableByteCount()];
            buffer.read(bytes);
            result.append(new String(bytes, StandardCharsets.UTF_8));
            DataBufferUtils.release(buffer);
        }
        return result.toString();
    }


