    private RenderCapture renderAndCapture(
            final String expectedTemplateName,
            final Set<String> expectedMarkupSelectors,
            final Set<String> markupSelectorsToRender,
            final Map<String, ?> model) throws Exception {

        doAnswer(invocation -> {
            final Writer writer = invocation.getArgument(3);
            writer.write("rendered");
            return null;
        }).when(this.templateEngine).process(
                anyString(), any(), any(IContext.class), any(Writer.class));

        this.view.renderFragment(markupSelectorsToRender, model, this.request, this.response);

        final ArgumentCaptor<IContext> contextCaptor = ArgumentCaptor.forClass(IContext.class);
        final ArgumentCaptor<Writer> writerCaptor = ArgumentCaptor.forClass(Writer.class);
        if (expectedMarkupSelectors == null) {
            verify(this.templateEngine).process(
                    eq(expectedTemplateName), isNull(), contextCaptor.capture(), writerCaptor.capture());
        } else {
            verify(this.templateEngine).process(
                    eq(expectedTemplateName), eq(expectedMarkupSelectors), contextCaptor.capture(), writerCaptor.capture());
        }

        return new RenderCapture(contextCaptor.getValue(), writerCaptor.getValue());
    }


    private static final class RenderCapture {

        private final IContext context;
        private final Writer writer;

        private RenderCapture(final IContext context, final Writer writer) {
            this.context = context;
            this.writer = writer;
        }
    }


    private static final class TrackingPrintWriter extends PrintWriter {

        private int flushCount = 0;

        private TrackingPrintWriter(final Writer out) {
            super(out);
        }

        @Override
        public void flush() {
            this.flushCount++;
            super.flush();
        }

        private int getFlushCount() {
            return this.flushCount;
        }
    }

}

