    @Test
    @DisplayName("A stopped throttle queues the event without touching the rest of the handler chain")
    void queuesEventWhenThrottlingHasStoppedProcessing() {
        final Fixture fixture = new Fixture(true);
        final IStandaloneElementTag tag = fixture.parse("<mytag />");

        fixture.flowController.stopProcessing = true;
        fixture.handler.handleStandaloneElement(tag);

        assertTrue(fixture.next.events.isEmpty(), "The event must not be delegated while processing is stopped");
        assertTrue(fixture.flowController.processorTemplateHandlerPending, "The queued event must mark the handler as pending");
        assertEquals(0, fixture.context.level(), "Queueing must happen before the context level is increased");

        fixture.flowController.stopProcessing = false;
        fixture.handler.handlePending();

        assertEvents(fixture, "standalone:mytag");
        assertFalse(fixture.flowController.processorTemplateHandlerPending);
        assertEquals(0, fixture.context.level(), "Pending processing must leave the context level balanced");
    }


