    private static void assertEvents(final Fixture fixture, final String... expected) {
        final List<String> actual = new ArrayList<String>(fixture.next.events.size());
        for (final ITemplateEvent event : fixture.next.events) {
            actual.add(describe(event));
        }
        assertEquals(Arrays.asList(expected), actual);
    }


    private static String describe(final ITemplateEvent event) {
        if (event instanceof IText) {
            return "text:" + ((IText) event).getText();
        }
        if (event instanceof IStandaloneElementTag) {
            return "standalone:" + ((IStandaloneElementTag) event).getElementCompleteName();
        }
        if (event instanceof IOpenElementTag) {
            return "open:" + ((IOpenElementTag) event).getElementCompleteName();
        }
        if (event instanceof ICloseElementTag) {
            return "close:" + ((ICloseElementTag) event).getElementCompleteName();
        }
        return event.getClass().getSimpleName();
    }


