        when(this.context.getConfiguration()).thenReturn(this.configuration);
        when(this.configuration.getElementDefinitions()).thenReturn(mock(ElementDefinitions.class));
        when(this.configuration.getAttributeDefinitions()).thenReturn(mock(AttributeDefinitions.class));
        when(this.configuration.getTemplateBoundariesProcessors(any(TemplateMode.class)))
                .thenReturn(Collections.emptySet());
        when(this.configuration.getCDATASectionProcessors(any(TemplateMode.class)))
                .thenReturn(Collections.emptySet());
        when(this.configuration.getCommentProcessors(any(TemplateMode.class)))
                .thenReturn(Collections.emptySet());
        when(this.configuration.getDocTypeProcessors(any(TemplateMode.class)))
                .thenReturn(Collections.emptySet());
        when(this.configuration.getProcessingInstructionProcessors(any(TemplateMode.class)))
                .thenReturn(Collections.emptySet());
        when(this.configuration.getTextProcessors(any(TemplateMode.class)))
                .thenReturn(Collections.emptySet());
        when(this.configuration.getXMLDeclarationProcessors(any(TemplateMode.class)))
