    @Test
    void noDocTypeProcessorsForwardsTheOriginalEventDirectly() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        createHandler();

        this.handler.handleDocType(docType);

        verify(this.next).handleDocType(same(docType));
        verifyNoMoreInteractions(this.next);
    }

    @Test
    void processorInstructionsChangeTheDocTypeForwardedDownTheChain() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor processor = mock(IDocTypeProcessor.class);
        doAnswer(invocation -> {
            final IDocTypeStructureHandler structureHandler = invocation.getArgument(2);
            structureHandler.setDocType(
                    "DOCTYPE", "svg",
                    "-//W3C//DTD SVG 1.1//EN",
                    "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd",
                    "<!ENTITY shape \"rect\">");
            return null;
        }).when(processor).process(
                any(ITemplateContext.class), any(IDocType.class), any(IDocTypeStructureHandler.class));

        createHandler(processor);
        this.handler.handleDocType(docType);

        final ArgumentCaptor<IDocType> captor = ArgumentCaptor.forClass(IDocType.class);
        verify(this.next).handleDocType(captor.capture());
        final IDocType result = captor.getValue();
        assertNotSame(docType, result);
        assertEquals("DOCTYPE", result.getKeyword());
        assertEquals("svg", result.getElementName());
        assertEquals("PUBLIC", result.getType());
        assertEquals("-//W3C//DTD SVG 1.1//EN", result.getPublicId());
        assertEquals("http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd", result.getSystemId());
        assertEquals("<!ENTITY shape \"rect\">", result.getInternalSubset());
        verify(processor).process(same(this.context), same(docType), any(IDocTypeStructureHandler.class));
        verifyNoMoreInteractions(this.next);
    }

    @Test
    void setDocTypeByOneProcessorIsVisibleToTheNextProcessorAndTheChain() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor firstProcessor = mock(IDocTypeProcessor.class);
        final IDocTypeProcessor secondProcessor = mock(IDocTypeProcessor.class);
        doAnswer(invocation -> {
            ((IDocTypeStructureHandler) invocation.getArgument(2))
                    .setDocType("DOCTYPE", "html", "public-id", "system-id", null);
            return null;
        }).when(firstProcessor).process(
                any(ITemplateContext.class), any(IDocType.class), any(IDocTypeStructureHandler.class));

        createHandler(firstProcessor, secondProcessor);
        this.handler.handleDocType(docType);

        final ArgumentCaptor<IDocType> processorCaptor = ArgumentCaptor.forClass(IDocType.class);
        verify(secondProcessor).process(
                same(this.context), processorCaptor.capture(), any(IDocTypeStructureHandler.class));
        assertEquals("public-id", processorCaptor.getValue().getPublicId());
        assertEquals("system-id", processorCaptor.getValue().getSystemId());

        final ArgumentCaptor<IDocType> nextCaptor = ArgumentCaptor.forClass(IDocType.class);
        verify(this.next).handleDocType(nextCaptor.capture());
        assertSame(processorCaptor.getValue(), nextCaptor.getValue());
    }

    @Test
    void structureHandlerIsResetBeforeEachProcessorRuns() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor firstProcessor = mock(IDocTypeProcessor.class);
        final IDocTypeProcessor secondProcessor = mock(IDocTypeProcessor.class);
        doAnswer(invocation -> {
            ((IDocTypeStructureHandler) invocation.getArgument(2))
                    .setDocType("DOCTYPE", "html", null, null, null);
            return null;
        }).when(firstProcessor).process(
                any(ITemplateContext.class), any(IDocType.class), any(IDocTypeStructureHandler.class));
        doAnswer(invocation -> {
            final DocTypeStructureHandler structureHandler = invocation.getArgument(2);
            assertFalse(structureHandler.setDocType);
            assertFalse(structureHandler.replaceWithModel);
            assertFalse(structureHandler.removeDocType);
            return null;
        }).when(secondProcessor).process(
                any(ITemplateContext.class), any(IDocType.class), any(IDocTypeStructureHandler.class));

        createHandler(firstProcessor, secondProcessor);
        this.handler.handleDocType(docType);

        verify(secondProcessor).process(
                same(this.context), any(IDocType.class), any(IDocTypeStructureHandler.class));
        verify(this.next).handleDocType(any(IDocType.class));
    }

    @Test
    void removeDocTypeDispatchesNoEvent() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
