    @Test
    void nonProcessableReplacementModelIsSentDirectlyToTheNextHandler() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor processor = mock(IDocTypeProcessor.class);
        final ITextProcessor textProcessor = mock(ITextProcessor.class);
        when(this.configuration.getTextProcessors(TemplateMode.HTML))
