    @Test
    void discardInstructionStopsExecutionOfLaterProcessors() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor firstProcessor = mock(IDocTypeProcessor.class);
        final IDocTypeProcessor secondProcessor = mock(IDocTypeProcessor.class);

        final Text replacementText = new Text("replacement");
        final Model replacementModel = new Model(this.configuration, TemplateMode.HTML);
        replacementModel.add(replacementText);
        doAnswer(invocation -> {
