    @Test
    void genericDocTypeIsConvertedToEngineDocTypeBeforeProcessorExecution() {
        final IDocType genericDocType = mock(IDocType.class);
        when(genericDocType.getKeyword()).thenReturn("DOCTYPE");
        when(genericDocType.getElementName()).thenReturn("html");
        when(genericDocType.getPublicId()).thenReturn("public-id");
        when(genericDocType.getSystemId()).thenReturn("system-id");
        when(genericDocType.getInternalSubset()).thenReturn("subset");
        when(genericDocType.getTemplateName()).thenReturn("template.html");
        when(genericDocType.getLine()).thenReturn(12);
        when(genericDocType.getCol()).thenReturn(34);

        final IDocTypeProcessor processor = mock(IDocTypeProcessor.class);
        createHandler(processor);
        this.handler.handleDocType(genericDocType);

        final ArgumentCaptor<IDocType> processorCaptor = ArgumentCaptor.forClass(IDocType.class);
        verify(processor).process(
                same(this.context), processorCaptor.capture(), any(IDocTypeStructureHandler.class));
        final IDocType engineDocType = processorCaptor.getValue();
        assertNotSame(genericDocType, engineDocType);
        assertTrue(engineDocType instanceof DocType);
        assertEquals("DOCTYPE", engineDocType.getKeyword());
        assertEquals("html", engineDocType.getElementName());
        assertEquals("public-id", engineDocType.getPublicId());
        assertEquals("system-id", engineDocType.getSystemId());
        assertEquals("subset", engineDocType.getInternalSubset());
        assertEquals("template.html", engineDocType.getTemplateName());
        assertEquals(12, engineDocType.getLine());
        assertEquals(34, engineDocType.getCol());

        verify(this.next).handleDocType(same(engineDocType));
    }

    @Test
    void stoppedThrottledHandlerQueuesTheDocTypeAndProcessesItOnResume() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor processor = mock(IDocTypeProcessor.class);
        createHandler(processor);

        final TemplateFlowController flowController = new TemplateFlowController();
        flowController.stopProcessing = true;
        this.handler.setFlowController(flowController);

        this.handler.handleDocType(docType);

        verify(processor, never()).process(
                any(ITemplateContext.class), any(IDocType.class), any(IDocTypeStructureHandler.class));
        verify(this.next, never()).handleDocType(any(IDocType.class));
        assertTrue(flowController.processorTemplateHandlerPending);

        flowController.stopProcessing = false;
        this.handler.handlePending();

        verify(processor).process(same(this.context), same(docType), any(IDocTypeStructureHandler.class));
        verify(this.next).handleDocType(same(docType));
        assertFalse(flowController.processorTemplateHandlerPending);
        verifyNoMoreInteractions(this.next);
    }

    @Test
    void pendingDocTypeStaysQueuedWhileThrottlingRemainsStopped() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor processor = mock(IDocTypeProcessor.class);
        createHandler(processor);

        final TemplateFlowController flowController = new TemplateFlowController();
        flowController.stopProcessing = true;
        this.handler.setFlowController(flowController);
        this.handler.handleDocType(docType);

        this.handler.handlePending();

        verify(processor, never()).process(
                any(ITemplateContext.class), any(IDocType.class), any(IDocTypeStructureHandler.class));
        verify(this.next, never()).handleDocType(any(IDocType.class));
        assertTrue(flowController.processorTemplateHandlerPending);
    }

    @Test
    void replacementModelIsQueuedAndProcessedWhenThrottlingIsEnabledButNotStopped() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor processor = mock(IDocTypeProcessor.class);

        final Text replacementText = new Text("replacement");
        final Model replacementModel = new Model(this.configuration, TemplateMode.HTML);
        replacementModel.add(replacementText);
        doAnswer(invocation -> {
            ((IDocTypeStructureHandler) invocation.getArgument(2))
                    .replaceWith(replacementModel, false);
            return null;
        }).when(processor).process(
                any(ITemplateContext.class), any(IDocType.class), any(IDocTypeStructureHandler.class));

        createHandler(processor);
        final TemplateFlowController flowController = new TemplateFlowController();
        this.handler.setFlowController(flowController);

        this.handler.handleDocType(docType);

        verify(this.next, never()).handleDocType(any(IDocType.class));
        verify(this.next).handleText(same(replacementText));
        assertFalse(flowController.processorTemplateHandlerPending);
    }

    @Test
    void skippedDocTypeIsNeitherProcessedNorForwarded() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor processor = mock(IDocTypeProcessor.class);
        createHandler(processor);

        final TemplateModelController modelController = mock(TemplateModelController.class);
        when(modelController.shouldProcessDocType(any(IDocType.class))).thenReturn(false);
        setField(this.handler, "modelController", modelController);

        this.handler.handleDocType(docType);

        verify(modelController).shouldProcessDocType(same(docType));
        verify(processor, never()).process(
                any(ITemplateContext.class), any(IDocType.class), any(IDocTypeStructureHandler.class));
        verify(this.next, never()).handleDocType(any(IDocType.class));
    }

    @Test
    void exceptionFromProcessorPropagatesAndPreventsFurtherProcessing() {
        final DocType docType = new DocType("DOCTYPE", "html", null, null, null);
        final IDocTypeProcessor processor = mock(IDocTypeProcessor.class);
        doAnswer(invocation -> {
            throw new IllegalStateException("processor failure");
        }).when(processor).process(
                any(ITemplateContext.class), any(IDocType.class), any(IDocTypeStructureHandler.class));

        createHandler(processor);

        final IllegalStateException exception = assertThrows(
                IllegalStateException.class, () -> this.handler.handleDocType(docType));

        assertEquals("processor failure", exception.getMessage());
        verify(this.next, never()).handleDocType(any(IDocType.class));
    }

    private void createHandler(final IDocTypeProcessor... processors) {
        final Set<IDocTypeProcessor> processorSet =
                new LinkedHashSet<IDocTypeProcessor>(Arrays.asList(processors));
        when(this.configuration.getDocTypeProcessors(TemplateMode.HTML)).thenReturn(processorSet);
        this.handler = new ProcessorTemplateHandler();
        this.handler.setContext(this.context);
        this.handler.setNext(this.next);
    }

    private static void setField(final Object target, final String fieldName, final Object value) {
        try {
            final Field field = ProcessorTemplateHandler.class.getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (final ReflectiveOperationException e) {
            throw new AssertionError("Could not set field '" + fieldName + "'", e);
        }
    }

}

