    private StubTemplateContext context;
    private TemplateManager templateManager;
    private StandardCacheManager cacheManager;
    private ICache<TemplateCacheKey, TemplateModel> templateCache;


    @BeforeEach
    void setUp() {
        this.resolver = new TrackingTemplateResolver();
        this.resolutionAttributes = new LinkedHashMap<String, Object>();
        this.resolutionAttributes.put("attribute", "value");

        final TemplateData ownerData = new TemplateData(
                OWNER_TEMPLATE, null, new StringTemplateResource("owner"),
                TemplateMode.HTML, AlwaysValidCacheEntryValidity.INSTANCE);
        this.context = new StubTemplateContext(ownerData, this.resolutionAttributes);

        final TemplateEngine engine = new TemplateEngine();
        engine.setTemplateResolver(this.resolver);
        this.cacheManager = new StandardCacheManager();
        engine.setCacheManager(this.cacheManager);

        this.templateManager = engine.getConfiguration().getTemplateManager();
        this.templateCache = this.cacheManager.getTemplateCache();
    }


    @Test
    void rejectsNullContextBeforeDoingAnythingElse() {
        final IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> this.templateManager.parseStandalone(
                        null, TEMPLATE_NAME, null, null, false, false));

        assertEquals("Context cannot be null", exception.getMessage());
        assertEquals(0, this.resolver.calls);
    }


    @Test
    void rejectsNullTemplateBeforeResolution() {
        final IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> this.templateManager.parseStandalone(
                        this.context, null, null, null, false, false));

        assertEquals("Template cannot be null", exception.getMessage());
        assertEquals(0, this.resolver.calls);
    }


