    @Test
    void parsesTemplateUsingResolverModeAndPassesResolutionArgumentsToResolver() throws Exception {
        this.resolver.resolution = resolution(
                new TrackingTemplateResource("<p>Hello</p>", true), TemplateMode.HTML, true,
                AlwaysValidCacheEntryValidity.INSTANCE);

        final TemplateModel model = this.templateManager.parseStandalone(
                this.context, TEMPLATE_NAME, null, null, false, true);

        assertNotNull(model);
        assertEquals("<p>Hello</p>", write(model));
        assertEquals(TEMPLATE_NAME, model.getTemplateData().getTemplate());
        assertEquals(TemplateMode.HTML, model.getTemplateData().getTemplateMode());
        assertFalse(model.getTemplateData().hasTemplateSelectors());
        assertNull(model.getTemplateData().getTemplateSelectors());
        assertSame(NonCacheableCacheEntryValidity.INSTANCE, model.getTemplateData().getValidity());

        assertEquals(1, this.resolver.calls);
        assertEquals(OWNER_TEMPLATE, this.resolver.lastOwnerTemplate);
        assertEquals(TEMPLATE_NAME, this.resolver.lastTemplate);
        assertSame(this.resolutionAttributes, this.resolver.lastResolutionAttributes);
    }


    @Test
    void explicitTemplateModeOverridesTheResolvedMode() throws Exception {
        this.resolver.resolution = resolution(
                new TrackingTemplateResource("raw [content]"), TemplateMode.HTML, true,
                AlwaysValidCacheEntryValidity.INSTANCE);

        final TemplateModel model = this.templateManager.parseStandalone(
                this.context, TEMPLATE_NAME, null, TemplateMode.RAW, false, true);

        assertNotNull(model);
        assertEquals(TemplateMode.RAW, model.getTemplateData().getTemplateMode());
        assertEquals("raw [content]", write(model));
    }


    @Test
    void nullTemplateModeIsKeptInCacheKeyWhileResolvedModeIsUsedForParsing() throws Exception {
        final ICacheEntryValidity validity = new AlwaysValidCacheEntryValidity();
        this.resolver.resolution = resolution(
                new TrackingTemplateResource("<div>cached</div>"), TemplateMode.HTML, true, validity);

        final TemplateModel model = this.templateManager.parseStandalone(
                this.context, TEMPLATE_NAME, null, null, true, true);

        assertNotNull(model);
        assertEquals(TemplateMode.HTML, model.getTemplateData().getTemplateMode());
        assertSame(validity, model.getTemplateData().getValidity());
        assertEquals(1, this.templateCache.keySet().size());

        final TemplateCacheKey cacheKey = this.templateCache.keySet().iterator().next();
        assertEquals(OWNER_TEMPLATE, cacheKey.getOwnerTemplate());
        assertEquals(TEMPLATE_NAME, cacheKey.getTemplate());
        assertNull(cacheKey.getTemplateMode());
        assertNull(cacheKey.getTemplateSelectors());
        assertEquals(0, cacheKey.getLineOffset());
        assertEquals(0, cacheKey.getColOffset());
        assertSame(this.resolutionAttributes, cacheKey.getTemplateResolutionAttributes());
    }


    @Test
    void multipleSelectorsAreSortedAndCachedInNaturalOrder() throws Exception {
        this.resolver.resolution = resolution(
                new TrackingTemplateResource("<p>selected</p>"), TemplateMode.HTML, true,
                AlwaysValidCacheEntryValidity.INSTANCE);
        final Set<String> selectors = new LinkedHashSet<String>(
                Arrays.asList("zeta", "alpha", "middle"));

        final TemplateModel model = this.templateManager.parseStandalone(
                this.context, TEMPLATE_NAME, selectors, TemplateMode.HTML, true, true);

        final List<String> orderedSelectors =
                new ArrayList<String>(model.getTemplateData().getTemplateSelectors());
        assertEquals(Arrays.asList("alpha", "middle", "zeta"), orderedSelectors);
        assertThrows(
                UnsupportedOperationException.class,
                () -> model.getTemplateData().getTemplateSelectors().add("another"));

        final TemplateCacheKey cacheKey = this.templateCache.keySet().iterator().next();
        assertEquals(
                new TreeSet<String>(Arrays.asList("alpha", "middle", "zeta")),
                cacheKey.getTemplateSelectors());
        assertEquals(
                Arrays.asList("alpha", "middle", "zeta"),
                new ArrayList<String>(cacheKey.getTemplateSelectors()));
    }


    @Test
    void singleSelectorIsRetainedAndEmptySelectorSetIsTreatedAsNoSelectors() throws Exception {
        this.resolver.resolution = resolution(
                new TrackingTemplateResource("<p>selected</p>"), TemplateMode.HTML, true,
                AlwaysValidCacheEntryValidity.INSTANCE);

        final Set<String> singleSelector = new LinkedHashSet<String>(Collections.singleton("only"));
        final TemplateModel singleSelectorModel = this.templateManager.parseStandalone(
                this.context, "single-selector-template", singleSelector, TemplateMode.HTML, false, true);
        assertEquals(Collections.singleton("only"), singleSelectorModel.getTemplateData().getTemplateSelectors());

        final TemplateModel emptySelectorModel = this.templateManager.parseStandalone(
                this.context, "empty-selector-template", Collections.<String>emptySet(), TemplateMode.HTML, false, true);
        assertFalse(emptySelectorModel.getTemplateData().hasTemplateSelectors());
        assertNull(emptySelectorModel.getTemplateData().getTemplateSelectors());
    }


    @Test
    void cachesParsedModelAndReturnsTheCachedModelOnSubsequentCalls() throws Exception {
        this.resolver.resolution = resolution(
                new TrackingTemplateResource("<p>cached</p>"), TemplateMode.HTML, true,
                AlwaysValidCacheEntryValidity.INSTANCE);

        final TemplateModel first =
                this.templateManager.parseStandalone(this.context, TEMPLATE_NAME, null, null, true, true);
        final TemplateModel second =
                this.templateManager.parseStandalone(this.context, TEMPLATE_NAME, null, null, true, true);

        assertNotNull(first);
        assertSame(first, second);
        assertEquals(1, this.resolver.calls);
        assertEquals(1, this.templateCache.keySet().size());
        assertEquals("<p>cached</p>", write(second));
    }


