    @Test
    void appliesPreProcessorsToFreshAndCachedModelsWithoutResolvingAgain() throws Exception {
        CountingPreProcessorHandler.reset();

        final TrackingTemplateResolver localResolver = new TrackingTemplateResolver();
        localResolver.resolution = resolution(
                new TrackingTemplateResource("<p>preprocessed</p>"), TemplateMode.HTML, true,
                AlwaysValidCacheEntryValidity.INSTANCE);

        final TemplateEngine engine = new TemplateEngine();
        engine.setDialect(new CountingPreProcessorDialect());
        engine.setTemplateResolver(localResolver);
        engine.setCacheManager(new StandardCacheManager());
        final TemplateManager manager = engine.getConfiguration().getTemplateManager();

        final TemplateModel first = manager.parseStandalone(
                this.context, TEMPLATE_NAME, null, null, true, true);
        assertEquals("<p>preprocessed</p>", write(first));
        assertEquals(1, CountingPreProcessorHandler.textInvocations.get());

        final TemplateModel second = manager.parseStandalone(
                this.context, TEMPLATE_NAME, null, null, true, true);
        assertEquals("<p>preprocessed</p>", write(second));
        assertEquals(2, CountingPreProcessorHandler.textInvocations.get());
        assertEquals(1, localResolver.calls);
    }


    private static TemplateResolution resolution(
            final ITemplateResource resource, final TemplateMode templateMode,
            final boolean existenceVerified, final ICacheEntryValidity validity) {
        return new TemplateResolution(resource, existenceVerified, templateMode, false, validity);
    }


    private static String write(final TemplateModel model) throws IOException {
        final StringWriter writer = new StringWriter();
        model.write(writer);
        return writer.toString();
    }


    private static final class TrackingTemplateResolver implements ITemplateResolver {

        private TemplateResolution resolution;
        private int calls;
        private String lastOwnerTemplate;
        private String lastTemplate;
        private Map<String, Object> lastResolutionAttributes;

        @Override
        public String getName() {
            return "tracking-resolver";
        }

        @Override
        public Integer getOrder() {
            return Integer.valueOf(0);
        }

        @Override
        public TemplateResolution resolveTemplate(
                final IEngineConfiguration configuration,
                final String ownerTemplate,
                final String template,
                final Map<String, Object> templateResolutionAttributes) {
            this.calls++;
            this.lastOwnerTemplate = ownerTemplate;
            this.lastTemplate = template;
            this.lastResolutionAttributes = templateResolutionAttributes;
            return this.resolution;
        }
    }


    private static final class TrackingTemplateResource implements ITemplateResource {

        private final String content;
        private final boolean exists;
        private int existsCalls;
        private int readerCalls;

        private TrackingTemplateResource(final String content) {
            this(content, true);
        }

        private TrackingTemplateResource(final String content, final boolean exists) {
            this.content = content;
            this.exists = exists;
        }

        @Override
        public String getDescription() {
            return "tracking-resource";
        }

        @Override
        public String getBaseName() {
            return "tracking-resource";
        }

        @Override
        public boolean exists() {
            this.existsCalls++;
            return this.exists;
        }

        @Override
        public Reader reader() {
            this.readerCalls++;
            return new StringReader(this.content);
        }

        @Override
        public ITemplateResource relative(final String relativeLocation) {
            throw new UnsupportedOperationException("Relative resources are not used in these tests");
        }
    }


