    public static final class CountingPreProcessorHandler extends AbstractTemplateHandler {

        private static final AtomicInteger textInvocations = new AtomicInteger(0);

        public CountingPreProcessorHandler() {
            super();
        }

        static void reset() {
            textInvocations.set(0);
        }

        @Override
        public void handleText(final IText text) {
            textInvocations.incrementAndGet();
            super.handleText(text);
        }
    }


    private static final class CountingPreProcessorDialect implements IPreProcessorDialect {

        @Override
        public String getName() {
            return "counting-preprocessor-dialect";
        }

        @Override
        public int getDialectPreProcessorPrecedence() {
            return 0;
        }

        @Override
        public Set<IPreProcessor> getPreProcessors() {
            return Collections.<IPreProcessor>singleton(
                    new PreProcessor(TemplateMode.HTML, CountingPreProcessorHandler.class, 0));
        }
    }
